class CodeReviewCandidate:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        from functools import lru_cache

        @lru_cache(None)
        def dfs(node: int, time_left: int, visited_mask: int) -> float:
            neighbors = [
                v for v in graph[node]
                if not (visited_mask >> (v - 1)) & 1
            ]

            if time_left == 0:
                return 1.0 if node == target else 0.0

            if node == target:
                # If there are no unvisited neighbors, the frog stays here
                # for all remaining seconds.
                return 1.0 if not neighbors else 0.0

            if not neighbors:
                return 0.0

            total = 0.0
            for nxt in neighbors:
                total += dfs(
                    nxt,
                    time_left - 1,
                    visited_mask | (1 << (nxt - 1))
                ) / len(neighbors)
            return total

        return dfs(1, t, 1 << 0)

