class CodeReviewCandidate:
    def kSimilarity(self, s1: str, s2: str) -> int:
        from collections import deque

        q = deque([s1])
        visited = {s1}
        dist = 0

        while q:
            for _ in range(len(q)):
                cur = q.popleft()

                if cur == s2:
                    return dist

                i = 0
                while i < len(cur) and cur[i] == s2[i]:
                    i += 1

                # Generate every useful swap candidate. Restricting this
                # to the first matching character is not sufficient when
                # characters are repeated.
                for j in range(i + 1, len(cur)):
                    if cur[j] != s2[i]:
                        continue
                    if cur[j] == s2[j]:
                        continue

                    chars = list(cur)
                    chars[i], chars[j] = chars[j], chars[i]
                    nxt = ''.join(chars)

                    if nxt not in visited:
                        visited.add(nxt)
                        q.append(nxt)

            dist += 1

        return -1

