class CodeReviewCandidate:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        tree = None
        outcome = []
        for i, x in enumerate(nums):
            tree = insert(tree, x)
            if size(tree) > k:
                tree = remove(tree, nums[i - k])
            if size(tree) == k:
                if k % 2 == 1:
                    outcome.append(get(tree, k // 2 + 1))
                else:
                    outcome.append((get(tree, k // 2) + get(tree, k // 2 + 1)) / 2)
        return outcome


class Node:
